update training_exercises set name=case when equipment='Plate' then 'Plate-Loaded Hip Thrust' else 'Bodyweight Hip Thrust' end,variation_label=case when equipment='Plate' then 'Plate-Loaded Hip Thrust' else 'Bodyweight Hip Thrust' end,aliases=(select array_agg(distinct a) from unnest(aliases||array['Hip Thrust'])a) where name='Hip Thrust' and equipment in('Plate','None / Bodyweight');
update training_exercises set name=case when equipment='Dumbbell' then 'Dumbbell Step-Up' else 'Bodyweight Step-Up' end,variation_label=case when equipment='Dumbbell' then 'Dumbbell Step-Up' else 'Bodyweight Step-Up' end,aliases=(select array_agg(distinct a) from unnest(aliases||array['Step-Up','Step Ups'])a) where name='Step-Up' and equipment in('Dumbbell','None / Bodyweight');